trait OptionBoolExt {
    fn transpose(self) -> Result<Option<bool>, ()>;
}

impl OptionBoolExt for Option<Option<bool>> {
    fn transpose(self) -> Result<Option<bool>, ()> {
        match self {
            None => Ok(None),
            Some(Some(value)) => Ok(Some(value)),
            Some(None) => Err(()),
        }
    }
}
